WITH parsed AS (SELECT id, plan, tier_limits, discounts, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT plan, COUNT(DISTINCT plan) AS distinct_plans, APPROX_PERCENTILE(avg_tier_price, ARRAY(0.25, 0.5, 0.75)) AS avg_tier_price_quartiles, SUM(CASE WHEN plan = 'starter' THEN avg_tier_price ELSE 0 END) AS starter_avg_tier_price, COUNT(*) AS row_count, PERCENTILE_APPROX(avg_tier_price, ARRAY(0.25, 0.5, 0.75)) AS avg_tier_price_quartiles_2, COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) AS enterprise_count FROM parsed GROUP BY plan
